-- Study Abroad country content, BATCH 18: Colombia, Peru, Costa Rica, Panama, Uruguay.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('colombia', 'peru', 'costa-rica', 'panama', 'uruguay'));
UPDATE countries SET why_title = 'Why study in Colombia?', why_body = '<p>Colombia has a growing higher education system, with leading universities in Bogotá and Medellín, low costs and strong programmes in business, engineering, medicine, design and Spanish language.</p><ul><li>Established public and private universities</li><li>Low costs compared with North America and Europe</li><li>Spanish immersion in a vibrant country</li><li>Strong in business, medicine, design and engineering</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Stays over 180 days need a <strong>Visa V Estudiante</strong> (sources conflict on whether the older M student visa still exists). Students staying over three months register with Migración Colombia and receive a foreigner ID (Cédula de Extranjería).</p><ul><li>Admission letter from a recognised institution</li><li>Passport, photographs and proof of funds</li><li>Visa fees reported between US$52 and US$285; check your consulate</li><li>Register your visa with Migración Colombia within the deadline</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Colombian consulate (Cancillería), Migración Colombia and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Public universities have set calendars and entrance exams.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof (DELE or SIELE) for Spanish-taught programmes</li><li>Entrance exam for public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs depend on the university type.</p><ul><li>Universidad Nacional (UNAL): international tuition set at about US$1,000 (about COP 3,675,000) a semester, plus a one-time registration fee of US$175</li><li>Private universities: about US$6,000 a year on average, up to US$14,000 (estimate)</li><li>Living costs: about US$400-$800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'colombia';
UPDATE countries SET why_title = 'Why study in Peru?', why_body = '<p>Peru offers a mix of Andean and Amazon culture, strong universities in Lima such as PUCP and San Marcos, and low costs, with strengths in engineering, business, gastronomy and archaeology.</p><ul><li>Established universities in Lima</li><li>Strong in engineering, gastronomy, archaeology and business</li><li>Spanish immersion</li><li>Lower costs than many destinations</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>International students usually enter on a tourist visa and then change their migratory status at the Migrations Office in Lima, with the university providing the documents. Third-party sites describe a 90-day renewable student visa; confirm the current rule.</p><ul><li>Admission letter from a recognised Peruvian institution</li><li>Passport and photographs</li><li>International medical insurance before arrival (PUCP fact sheet)</li><li>Visa requirements, fees and processes change often</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Migraciones Peru and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. PUCP lists application windows around April-June and October-January.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at some universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees differ by university.</p><ul><li>PUCP: differentiated tuition scales, with 2026-1 undergraduate credit values of PEN 304.60 to 1,164.10 (third-party guide; check the official 2026-1 page)</li><li>San Marcos: estimated about PEN 16,038 a year for undergraduate and PEN 25,800-44,800 for graduate (unofficial, may be outdated)</li><li>Living costs: about US$400-$800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'peru';
UPDATE countries SET why_title = 'Why study in Costa Rica?', why_body = '<p>Costa Rica is known for its stable democracy, environmental leadership and biodiversity, with strong programmes in environmental science, tourism and Spanish language.</p><ul><li>Leading environmental and conservation studies</li><li>Stable, peaceful country</li><li>Spanish language immersion</li><li>Eco-tourism and agriculture strengths</li></ul>', visa_title = 'Student residence requirements', visa_body = '<p>Stays over 90 days require a student permit under the <strong>Special Category Student</strong> from the DGME. The process has two stages: a provisional visa to enter and a residence permit once you are in the country.</p><ul><li>Full-time enrolment and proof of funds</li><li>Valid health insurance and a return ticket (one source)</li><li>Application fee reported at about €232 (one guide)</li><li>Permit typically 1 year and renewable (one guide)</li><li>No right to work, and no direct path to permanent residence</li><li>Dependants (under 25) can get a 90-day dependant visa</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DGME Costa Rica and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. UCR admission rules for international applicants were not found in search.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>International undergraduates at the University of Costa Rica pay about CRC 58,410-59,140 per credit (about US$123-$125), according to a guide citing the fee schedule.</p><ul><li>Aid: international undergraduates do not have access to public scholarship programmes; postgraduates have somewhat better options</li><li>Living costs: about US$600-$1,000 a month (estimate)</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'costa-rica';
UPDATE countries SET why_title = 'Why study in Panama?', why_body = '<p>Panama is a regional business, logistics and banking hub, with private and public universities offering programmes in business, engineering, maritime and tourism. A new 2026 rule opens a permanent residency path for long-term foreign students.</p><ul><li>Regional hub for logistics, banking and maritime trade</li><li>Universities such as UTP and the University of Panama</li><li>Spanish and English language opportunities</li><li>New permanent residence path for students with 6+ consecutive years (Feb 2026)</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>The <strong>Temporary Residence Visa - Student</strong> is for formal studies. Depending on nationality, you may need permission to enter and permission to remain as a student resident.</p><ul><li>Acceptance letter from a recognised Panamanian institution</li><li>Government application fee reported at USD 100, with processing of 3-8 weeks (2026 FAQ)</li><li>The repatriation deposit is waived for students</li><li>New: a resolution of 6 February 2026 creates a permanent residency subcategory for foreign students with more than six consecutive years of study</li><li>Work is reported as up to 20 hours a week in term (third-party; confirm)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Servicio Nacional de Migración (migracion.gob.pa) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at public universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees differ by university, and UTP charges foreign students extra.</p><ul><li>UTP: a foreign student fee of B/.200 per academic period plus tuition, and B/.50 for the admission certificate</li><li>University of Panama tuition was not found; check directly</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'panama';
UPDATE countries SET why_title = 'Why study in Uruguay?', why_body = '<p>Uruguay is one of Latin America''s most stable and safe countries, with the public Universidad de la República (Udelar) reported to be tuition free for undergraduates, and strong regional exchange links.</p><ul><li>Stable, safe country with a high quality of life</li><li>Undergraduate degrees at Udelar reported as free</li><li>Exchange links across Latin America and Europe</li><li>Spanish immersion in a small, welcoming country</li></ul>', visa_title = 'Residence permit requirements', visa_body = '<p>Stays over 180 days require a <strong>temporary residence permit</strong> from the National Directorate of Migration (DNM), applied for after arrival and granted for up to one year, renewable.</p><ul><li>Passport, photo and a visa if your nationality needs one (DNM table, October 2026, shows ordinary Indian and Pakistani passports need a visa with prior authorisation)</li><li>Proof of sufficient funds (your own or a relative''s)</li><li>An interpreter if you do not speak Spanish</li><li>Health, accident and repatriation insurance for exchange students</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DNM Uruguay and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Exchange applicants apply through partner agreements, and degree-seeking students apply directly to each faculty. Some Udelar exchange calls require 40% of the degree passed.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof</li><li>Faculty-specific entrance requirements</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Public undergraduate study at Udelar is reported as free; exchange students usually pay no academic fees.</p><ul><li>Private universities such as Universidad de Montevideo charge fees; check each one</li><li>Udelar has no residences of its own for international exchange students</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'uruguay';
COMMIT;
